text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "工单整体概况统计",
      "business_question": "客服工单的总量、唯一编号数及响应时间的分布情况如何？",
      "priority": "P0",
      "priority_reason": "核心需求要求探索主要特征，整体规模与关键数值指标（响应分钟）的集中趋势是理解数据概况的基础。删除此任务将无法回答“数据有多少”及“典型响应速度是多少”的基本问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_ticket_count"
              },
              {
                "function": "distinct_count",
                "field": "field_0006",
                "alias": "unique_ticket_ids"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_response_minutes"
              },
              {
                "function": "median",
                "field": "field_0005",
                "alias": "median_response_minutes"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "各团队工单分布与响应差异",
      "business_question": "不同团队的工单数量分布如何？各团队的平均响应时间是否存在显著差异？",
      "priority": "P0",
      "priority_reason": "核心需求要求探索“差异”。团队是主要的组织维度，分析其数量分布和响应效率差异直接回应了“主要特征和差异”这一目标。这是识别资源分配不均或效率瓶颈的关键视角。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "ticket_count"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "team_avg_response"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "ticket_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "优先级与状态交叉分析",
      "business_question": "不同优先级的工单在状态上的分布有何特征？高优先级工单的处理进度是否优于低优先级？",
      "priority": "P1",
      "priority_reason": "优先级和状态是反映业务紧急程度和处理流程的核心分类字段。虽然不如团队维度直观，但交叉分析能揭示SLA执行情况和积压风险，属于对“主要特征”的深度补充。删除后仍可了解概况，但无法深入洞察处理流程中的潜在矛盾。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "status_count"
              }
            ],
            "dimensions": [
              "field_0004",
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "status_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "提交日期月度趋势概览",
      "business_question": "工单提交量在不同月份之间是否有波动规律？",
      "priority": "P2",
      "priority_reason": "探索式分析通常包含时间维度的初步观察。虽然样本量较小（8行），且未指定具体年份，但提取月份进行分组计数有助于发现季节性或周期性特征的线索。此为补充性分析，若数据量过小可能无显著意义，但不影响核心结论。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "submit_month"
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "monthly_ticket_count"
              }
            ],
            "dimensions": [
              "submit_month"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "submit_month",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
